@js:
let t = result.replace(/\r/g,'').replace(/\n+/g,'\n');
let start = t.search(/當|我|他|她|在|這|那|有一天|有一次|話說|正文|第[一二三四五六七八九十\d]+[章節回]/);
if(start < 0) start = t.indexOf('\n') > 0 ? t.indexOf('\n')+1 : 0;
let end = t.search(/全文完|☆★☆|分類\*|最新文章|分站|Page \d+ of/);
if(end < 0) end = t.length;
let content = t.substring(start, end).trim();
content = content.replace(/《\s*\[.*?\]\s*》/g,'').replace(/meme104|173免費|視訊|聊天網/g,'').trim();
content;
